104	func TestValidateHoursOverlap(t *testing.T) {
105		cases := []struct {
106			name    string
107			hours   []WeeklyHour
108			wantErr bool
109		}{
110			{"adjacent same day", []WeeklyHour{
111				{1, "10:00", "12:00"}, {1, "12:00", "14:00"},
112			}, false},
113			{"overlap same day", []WeeklyHour{
114				{1, "10:00", "12:00"}, {1, "11:00", "13:00"},
115			}, true},
116			{"containment", []WeeklyHour{
117				{1, "09:00", "18:00"}, {1, "10:00", "11:00"},
118			}, true},
119			{"different days no overlap", []WeeklyHour{
120				{1, "22:00", "02:00"}, {3, "01:00", "03:00"},
121			}, false},
122			// 需求示例：周一 22:00-02:00 与周二 01:00-03:00 必须拒绝。
123			{"cross midnight into next day", []WeeklyHour{
124				{1, "22:00", "02:00"}, {2, "01:00", "03:00"},
125			}, true},
126			// 跨午夜在次日整点结束，与下一天 02:00 开始的时段相邻，允许。
127			{"cross midnight adjacent to next day", []WeeklyHour{
128				{1, "22:00", "02:00"}, {2, "02:00", "04:00"},
129			}, false},
130			// 周日 22:00-02:00 延续到周一，与周一 01:00 冲突。
131			{"sunday spills into monday", []WeeklyHour{
132				{7, "22:00", "02:00"}, {1, "01:00", "03:00"},
133			}, true},
134			// 周日跨午夜在周一 00:00 结束，与周一时段相邻，允许。
135			{"sunday ends exactly monday midnight", []WeeklyHour{
136				{7, "22:00", "00:00"}, {1, "00:00", "02:00"},
137			}, false},
138			// 同一起点的两个时段也属于相交。
139			{"same start", []WeeklyHour{
140				{3, "08:00", "09:00"}, {3, "08:00", "10:00"},
141			}, true},
142		}
143		for _, tc := range cases {
144			t.Run(tc.name, func(t *testing.T) {
145				err := validateHours(tc.hours)
146				if tc.wantErr && err == nil {
147					t.Fatalf("expected overlap error")
148				}
149				if !tc.wantErr && err != nil {
150					t.Fatalf("unexpected error: %v", err)
151				}
152			})
153		}
154	}
