647	// TestParseJSONIntegerExact 直接验证按 JSON 数字原文做的精确整数判断：
648	// 不经过 float64，因此微小的小数部分不会被舍掉，超过 2^53 的整数也不会错位。
649	func TestParseJSONIntegerExact(t *testing.T) {
650		want := func(text string, value int64) {
651			t.Helper()
652			wantSign := 0
653			switch {
654			case value > 0:
655				wantSign = 1
656			case value < 0:
657				wantSign = -1
658			}
659			z, sign, isInt, inRange := parseJSONInteger(json.Number(text))
660			if !isInt || !inRange || sign != wantSign || z.Int64() != value {
661				t.Fatalf("%s: want in-range integer %d, got z=%v sign=%d isInt=%v inRange=%v",
662					text, value, z, sign, isInt, inRange)
663			}
664		}
665		wantNotInt := func(text string) {
666			t.Helper()
667			if _, _, isInt, _ := parseJSONInteger(json.Number(text)); isInt {
668				t.Fatalf("%s: must NOT be treated as an integer", text)
669			}
670		}
671		wantOutOfRange := func(text string) {
672			t.Helper()
673			z, _, isInt, inRange := parseJSONInteger(json.Number(text))
674			if !isInt || inRange || z != nil {
675				t.Fatalf("%s: want out-of-range integer (nil z), got z=%v isInt=%v inRange=%v",
676					text, z, isInt, inRange)
677			}
678		}
679	
680		// 三种合法写法都表示整数 120。
681		want("120", 120)
682		want("120.0", 120)
683		want("1.2e2", 120)
684		want("1200e-1", 120)
685		want("0.0", 0)
686		want("-3", -3)
687		want("9007199254740993", 9007199254740993) // 2^53+1，float64 无法表示
688		want("9223372036854775807", 9223372036854775807)
689		want("9.007199254740993e15", 9007199254740993)
690	
691		// 任何非零小数部分都必须被识别出来，无论它在 float64 中会不会被舍掉。
692		wantNotInt("120.00000000000000001")
693		wantNotInt("0.1")
694		wantNotInt("1e-1")
695		wantNotInt("120.0000000001")
696		wantNotInt("1.23456789012345678")
697		wantNotInt("1e-323") // 极小正数，走快速路径
698	
699		// 确实是整数但超出 int64：与“不是整数”区分开。
700		wantOutOfRange("9223372036854775808") // 2^63
701		wantOutOfRange("999999999999999999999999")
702		wantOutOfRange("1e100")
703		wantOutOfRange("1e1000000") // 极大指数，走快速路径
704	
705		// 非数字类型（HTTP 路径下 UseNumber 只把数字变成 json.Number）。
706		for _, v := range []any{"120", true, nil, []any{}, map[string]any{}} {
707			if _, _, isInt, _ := parseJSONInteger(v); isInt {
708				t.Fatalf("%v must not be parsed as an integer", v)
709			}
710		}
711	
712		// 进程内直接传 float64（测试/其它调用方）的兼容行为。
713		if z, _, isInt, inRange := parseJSONInteger(120.0); !isInt || !inRange || z.Int64() != 120 {
714			t.Fatalf("float64 120 should be accepted, got %v", z)
715		}
716		if _, _, isInt, _ := parseJSONInteger(12.5); isInt {
717			t.Fatalf("float64 12.5 must not be an integer")
718		}
719	}
