229	// ---- Fetch 闸门（Fetch 域拦截，POST 与 GET 共用同一个拦截会话）----
230	
231	// createApiGates 在同一个 Fetch.enable 会话上按方法分流：
232	//
233	//   - postGate 把发往 /api/venues 的 POST 暂停在“请求已经发出、响应尚未
234	//     返回”的阶段，真实复现“点击保存后、结果返回前继续编辑表单”的等待
235	//     窗口：pause() 之后遇到的下一个场地 POST 会被挂起，测试先在页面里
236	//     完成编辑，再决定放行到真实服务端（pass）或直接合成响应（fulfill，
237	//     例如 400）。
238	//   - getGate 同样挂起场地列表 GET，用于复现“读取交错”：页面打开时的
239	//     初次读取尚未结束，保存成功又触发一次较新的读取。两次 GET 各自可被
240	//     放行（pass，到真实服务端）、直接合成响应（fulfill：HTTP 错误、无法
241	//     解析的 JSON）或制造连接失败（fail），返回内容与先后顺序完全由测试
242	//     掌握。
243	//
244	// 同一 Fetch 会话只能有一个 requestPaused 监听器决定每个请求的去向，否则
245	// 一个闸门的“放行”会抢先释放另一个闸门想挂住的请求；这里由唯一的监听器
246	// 按方法查对应闸门的暂停状态。HTML 等其余请求一律立即放行。
247	function createApiGates(cdp) {
248	  function makeGate(method) {
249	    // held: id -> { id, requestId, url, body, done }
250	    const held = new Map();
251	    let seq = 0;
252	    let paused = false;
253	    let waiters = [];
254	
255	    async function onPaused(params) {
256	      // 挂起时立即取回请求体原文：此时尚未放行，内容必然是点击保存那一刻
257	      // 的快照，之后页面怎么改都影响不到它。
258	      let body = null;
259	      try {
260	        const out = await cdp.send("Fetch.getRequestBody", { requestId: params.requestId });
261	        body = out.base64Encoded ? Buffer.from(out.body, "base64").toString("utf8") : out.body;
262	      } catch {
263	        body = params.request.postData || null;
264	      }
265	      const id = ++seq;
266	      held.set(id, { id, requestId: params.requestId, url: params.request.url, body, done: false });
267	      const ws = waiters;
268	      waiters = [];
269	      for (const w of ws) w(id);
270	    }
271	
272	    const api = {
273	      pause() { paused = true; },
274	      resume() { paused = false; },
275	      // nextHold 等待下一个被挂起的请求；afterId 用于同一次暂停里连续挂住
276	      // 多个请求（初次读取、保存后刷新读取）时取“更新的那一个”。
277	      nextHold(timeout = 8000, afterId = 0) {
278	        for (const rec of held.values()) {
279	          if (!rec.done && rec.id > afterId) return Promise.resolve(rec.id);
280	        }
281	        return new Promise((resolve, reject) => {
282	          const timer = setTimeout(
283	            () => reject(new Error(`等待 ${method} /api/venues 被挂起超时`)), timeout);
284	          waiters.push(function waiter(id) {
285	            if (id <= afterId) { waiters.push(waiter); return; }
286	            clearTimeout(timer);
287	            resolve(id);
288	          });
289	        });
290	      },
291	      bodyOf(id) {
292	        const rec = held.get(id);
293	        return rec ? rec.body : null;
294	      },
295	      // pass 放行到真实服务端，由真实处理链给出响应。
296	      async pass(id) {
297	        const rec = held.get(id);
298	        if (!rec || rec.done) return;
299	        rec.done = true;
300	        await cdp.send("Fetch.continueRequest", { requestId: rec.requestId });
301	      },
302	      // fulfill 不接触真实服务端，直接合成一个响应，保证内容与时机完全可控
303	      // （失败的读取不会读到真实数据，失败的保存也不会在服务端落地）。
304	      async fulfill(id, status, payload, extraHeaders) {
305	        const rec = held.get(id);
306	        if (!rec || rec.done) return;
307	        rec.done = true;
308	        const raw = typeof payload === "string" ? payload : JSON.stringify(payload);
309	        const headers = [
310	          { name: "Content-Type", value: "application/json; charset=utf-8" },
311	          { name: "Content-Length", value: String(Buffer.byteLength(raw)) },
312	        ];
313	        for (const [name, value] of Object.entries(extraHeaders || {})) {
314	          headers.push({ name, value: String(value) });
315	        }
316	        await cdp.send("Fetch.fulfillRequest", {
317	          requestId: rec.requestId,
318	          responseCode: status,
319	          responseHeaders: headers,
320	          body: Buffer.from(raw, "utf8").toString("base64"),
321	        });
322	      },
323	      // fail 直接以网络错误终止该请求，模拟连接失败（fetch promise reject）。
324	      async fail(id, reason) {
325	        const rec = held.get(id);
326	        if (!rec || rec.done) return;
327	        rec.done = true;
328	        try {
329	          await cdp.send("Fetch.failRequest", {
330	            requestId: rec.requestId,
331	            errorReason: reason || "Failed",
332	          });
333	        } catch { /* 请求可能已失效 */ }
334	      },
335	      // continueAll 放行所有仍挂着的请求：场景中断时自愈，避免遗留 fetch
336	      // 永久挂起影响后续场景。
337	      async continueAll() {
338	        for (const rec of held.values()) {
339	          if (!rec.done) {
340	            rec.done = true;
341	            try {
342	              await cdp.send("Fetch.continueRequest", { requestId: rec.requestId });
343	            } catch { /* ignore */ }
344	          }
345	        }
346	      },
347	    };
348	
349	    return {
350	      // 由共享监听器调用：返回 true 表示该请求归本闸门挂起。
351	      wants(params) {
352	        return paused && params.request && params.request.method === method &&
353	          params.request.url.includes("/api/venues");
354	      },
355	      async hold(params) {
356	        try {
357	          await onPaused(params);
358	        } catch { /* 竞态失败交给场景断言处理 */ }
359	      },
360	      api,
361	    };
362	  }
363	
364	  const postGate = makeGate("POST");
365	  const getGate = makeGate("GET");
366	
367	  cdp.on((eventMethod, params) => {
368	    if (eventMethod !== "Fetch.requestPaused") return;
369	    (async () => {
370	      if (postGate.wants(params)) { await postGate.hold(params); return; }
371	      if (getGate.wants(params)) { await getGate.hold(params); return; }
372	      // 未被任何闸门暂停的场地请求（HTML/health 本来就不匹配 urlPattern）
373	      // 以及闸门 resume 之后到达的请求，一律立即放行。
374	      try {
375	        await cdp.send("Fetch.continueRequest", { requestId: params.requestId });
376	      } catch { /* 请求可能已失效，忽略 */ }
377	    })().catch(() => { /* 监听器内异常不能冒泡成 unhandledRejection */ });
378	  });
379	
380	  return {
381	    async enable() {
382	      await cdp.send("Fetch.enable", {
383	        patterns: [{ urlPattern: "*api/venues*", requestStage: "Request" }],
384	      });
385	    },
386	    post: postGate.api,
387	    get: getGate.api,
388	    async continueAll() {
389	      await postGate.api.continueAll();
390	      await getGate.api.continueAll();
391	    },
392	    // resetAll 恢复暂停状态并放行遗留请求，用于场景异常后的自愈。
393	    resetAll() {
394	      postGate.api.resume();
395	      getGate.api.resume();
396	      return this.continueAll();
397	    },
398	  };
399	}
