// 首页容量准确性端到端回归脚本（由 main_test.go 通过 go test 调用，不单独运行）。
//
// 用法：node homepage_browser_test.mjs <baseURL> [chrome 可执行文件路径]
//
// 脚本用 Chrome DevTools Protocol 驱动本机无头 Chrome 打开真实首页，覆盖
// “用户填表 → 提交 → 查看已保存场地”的完整链路；stdout 最后一行输出 JSON
// 结果。除浏览器/脚本自身的基础设施故障（退出码非 0）外，页面行为层面的
// 断言失败都记录在 JSON 的 checks 中，由 Go 测试统一判定。
//
// 设计要点：
//   - 直接启动系统 Chrome 并以裸 WebSocket（Node 24 全局 WebSocket）连接
//     CDP，不依赖任何 npm 包，适配无外网/无 node_modules 的环境。
//   - 监听 Network 事件，保存发往 /api/venues 的请求体原文与响应体原文，
//     因此可以逐字节验证 capacity 是否仍是未加引号的十进制整数。
//   - 表单取值通过原型 value setter + input/change 事件注入，真实触发
//     页面已有的提交逻辑，而不是直接调用内部函数。

import { spawn } from "node:child_process";
import fs from "node:fs";
import net from "node:net";
import os from "node:os";
import path from "node:path";

const baseURL = process.argv[2];
const chromeArg = process.argv[3] || "";
if (!baseURL) {
  console.error("usage: node homepage_browser_test.mjs <baseURL> [chrome]");
  process.exit(2);
}

function failInfra(message) {
  process.stdout.write(JSON.stringify({ harnessError: String(message) }) + "\n");
  process.exit(1);
}

process.on("unhandledRejection", (err) => failInfra(err && err.stack || err));

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function findChrome() {
  if (chromeArg) return chromeArg;
  if (process.env.CHROME_BIN) return process.env.CHROME_BIN;
  const candidates = [
    "/usr/bin/google-chrome",
    "/usr/bin/google-chrome-stable",
    "/usr/bin/chromium",
    "/usr/bin/chromium-browser",
    "/usr/local/bin/google-chrome",
  ];
  for (const c of candidates) {
    try {
      fs.accessSync(c, fs.constants.X_OK);
      return c;
    } catch { /* keep looking */ }
  }
  return "google-chrome";
}

function freePort() {
  return new Promise((resolve, reject) => {
    const srv = net.createServer();
    srv.listen(0, "127.0.0.1", () => {
      const p = srv.address().port;
      srv.close(() => resolve(p));
    });
    srv.on("error", reject);
  });
}

async function launchChrome() {
  const binary = findChrome();
  const port = await freePort();
  const profile = fs.mkdtempSync(path.join(os.tmpdir(), "tb-chrome-"));
  const args = [
    "--headless=new",
    "--no-sandbox",
    "--disable-gpu",
    "--disable-dev-shm-usage",
    "--no-first-run",
    "--no-default-browser-check",
    "--disable-background-networking",
    "--disable-crash-reporter",
    `--remote-debugging-port=${port}`,
    `--user-data-dir=${profile}`,
    "about:blank",
  ];
  const chrome = spawn(binary, args, {
    stdio: ["ignore", "ignore", "pipe"],
    detached: true,
  });
  let stderr = "";
  chrome.stderr.on("data", (d) => { stderr += d; });

  let info = null;
  for (let i = 0; i < 60; i++) {
    await sleep(100);
    try {
      const res = await fetch(`http://127.0.0.1:${port}/json/version`);
      if (res.ok) { info = await res.json(); break; }
    } catch { /* not ready */ }
  }
  if (!info) {
    try { process.kill(-chrome.pid, "SIGKILL"); } catch { /* ignore */ }
    failInfra(`Chrome 未在预期时间内开启 CDP（${binary}）：${stderr.slice(-400)}`);
  }
  const cleanup = () => {
    try { process.kill(-chrome.pid, "SIGKILL"); } catch { /* already gone */ }
    try { fs.rmSync(profile, { recursive: true, force: true }); } catch { /* ignore */ }
  };
  return { port, browserInfo: info, cleanup };
}

// ---- 极简 CDP 客户端 ----

class CDP {
  constructor(wsUrl) {
    this.ws = new WebSocket(wsUrl);
    this.nextId = 0;
    this.pending = new Map();
    this.eventListeners = [];
  }
  async connect() {
    await new Promise((resolve, reject) => {
      this.ws.addEventListener("open", resolve, { once: true });
      this.ws.addEventListener("error", reject, { once: true });
    });
    this.ws.addEventListener("message", (ev) => {
      const msg = JSON.parse(ev.data);
      if (msg.id && this.pending.has(msg.id)) {
        const { resolve, reject } = this.pending.get(msg.id);
        this.pending.delete(msg.id);
        if (msg.error) reject(new Error(`${msg.error.message || JSON.stringify(msg.error)}`));
        else resolve(msg.result);
        return;
      }
      if (msg.method) {
        for (const fn of this.eventListeners) {
          try { fn(msg.method, msg.params); } catch { /* listener errors must not break the run */ }
        }
      }
    });
  }
  on(fn) { this.eventListeners.push(fn); }
  send(method, params = {}) {
    const id = ++this.nextId;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      this.ws.send(JSON.stringify({ id, method, params }));
    });
  }
  close() { try { this.ws.close(); } catch { /* ignore */ } }

  // 在页面里求值；表达式必须是返回可 JSON 序列化值的同步表达式。
  async eval(expression) {
    const res = await this.send("Runtime.evaluate", {
      expression,
      returnByValue: true,
      awaitPromise: true,
    });
    if (res.exceptionDetails) {
      const exc = res.exceptionDetails.exception;
      throw new Error(`page exception: ${(exc && exc.description) || JSON.stringify(res.exceptionDetails)}`);
    }
    return res.result ? res.result.value : undefined;
  }
  async evalFn(fnSource, arg) {
    return this.eval(`(${fnSource})(${JSON.stringify(arg === undefined ? null : arg)})`);
  }
}

// ---- 网络记录 ----

function createNetworkLog(cdp) {
  // requests: requestId -> {method,url,postData,status,mimeType}
  const requests = new Map();
  cdp.on((method, params) => {
    if (method === "Network.requestWillBeSent") {
      const r = params.request;
      const rec = requests.get(params.requestId) || {};
      rec.method = r.method;
      rec.url = r.url;
      if (typeof r.postData === "string") rec.postData = r.postData;
      requests.set(params.requestId, rec);
    } else if (method === "Network.responseReceived") {
      const rec = requests.get(params.requestId) || {};
      rec.method = rec.method || params.request.method;
      rec.url = rec.url || params.request.url;
      rec.status = params.response.status;
      rec.mimeType = params.response.mimeType;
      requests.set(params.requestId, rec);
    }
  });
  const snapshot = () => Array.from(requests.values());
  return {
    snapshot,
    venuePosts(after = 0) {
      return snapshot()
        .filter((r) => r.method === "POST" && r.url.includes("/api/venues"))
        .slice(after);
    },
    venueGets() {
      return snapshot().filter((r) => r.method === "GET" && r.url.includes("/api/venues"));
    },
    async postDataOf(rec) {
      if (rec.postData !== undefined) return rec.postData;
      // requestWillBeSent 未携带 body 时按 requestId 补取。
      for (const [id, r] of requests) {
        if (r === rec) {
          try {
            const out = await cdp.send("Network.getRequestPostData", { requestId: id });
            return out.postData;
          } catch { return null; }
        }
      }
      return null;
    },
    async bodyOf(rec) {
      for (const [id, r] of requests) {
        if (r === rec) {
          const out = await cdp.send("Network.getResponseBody", { requestId: id });
          return out.base64Encoded ? Buffer.from(out.body, "base64").toString("utf8") : out.body;
        }
      }
      return null;
    },
  };
}

// ---- Fetch 闸门（Fetch 域拦截，POST 与 GET 共用同一个拦截会话）----

// createApiGates 在同一个 Fetch.enable 会话上按方法分流：
//
//   - postGate 把发往 /api/venues 的 POST 暂停在“请求已经发出、响应尚未
//     返回”的阶段，真实复现“点击保存后、结果返回前继续编辑表单”的等待
//     窗口：pause() 之后遇到的下一个场地 POST 会被挂起，测试先在页面里
//     完成编辑，再决定放行到真实服务端（pass）或直接合成响应（fulfill，
//     例如 400）。
//   - getGate 同样挂起场地列表 GET，用于复现“读取交错”：页面打开时的
//     初次读取尚未结束，保存成功又触发一次较新的读取。两次 GET 各自可被
//     放行（pass，到真实服务端）、直接合成响应（fulfill：HTTP 错误、无法
//     解析的 JSON）或制造连接失败（fail），返回内容与先后顺序完全由测试
//     掌握。
//
// 同一 Fetch 会话只能有一个 requestPaused 监听器决定每个请求的去向，否则
// 一个闸门的“放行”会抢先释放另一个闸门想挂住的请求；这里由唯一的监听器
// 按方法查对应闸门的暂停状态。HTML 等其余请求一律立即放行。
function createApiGates(cdp) {
  function makeGate(method) {
    // held: id -> { id, requestId, url, body, done }
    const held = new Map();
    let seq = 0;
    let paused = false;
    let waiters = [];

    async function onPaused(params) {
      // 挂起时立即取回请求体原文：此时尚未放行，内容必然是点击保存那一刻
      // 的快照，之后页面怎么改都影响不到它。
      let body = null;
      try {
        const out = await cdp.send("Fetch.getRequestBody", { requestId: params.requestId });
        body = out.base64Encoded ? Buffer.from(out.body, "base64").toString("utf8") : out.body;
      } catch {
        body = params.request.postData || null;
      }
      const id = ++seq;
      held.set(id, { id, requestId: params.requestId, url: params.request.url, body, done: false });
      const ws = waiters;
      waiters = [];
      for (const w of ws) w(id);
    }

    const api = {
      pause() { paused = true; },
      resume() { paused = false; },
      // nextHold 等待下一个被挂起的请求；afterId 用于同一次暂停里连续挂住
      // 多个请求（初次读取、保存后刷新读取）时取“更新的那一个”。
      nextHold(timeout = 8000, afterId = 0) {
        for (const rec of held.values()) {
          if (!rec.done && rec.id > afterId) return Promise.resolve(rec.id);
        }
        return new Promise((resolve, reject) => {
          const timer = setTimeout(
            () => reject(new Error(`等待 ${method} /api/venues 被挂起超时`)), timeout);
          waiters.push(function waiter(id) {
            if (id <= afterId) { waiters.push(waiter); return; }
            clearTimeout(timer);
            resolve(id);
          });
        });
      },
      bodyOf(id) {
        const rec = held.get(id);
        return rec ? rec.body : null;
      },
      // pass 放行到真实服务端，由真实处理链给出响应。
      async pass(id) {
        const rec = held.get(id);
        if (!rec || rec.done) return;
        rec.done = true;
        await cdp.send("Fetch.continueRequest", { requestId: rec.requestId });
      },
      // fulfill 不接触真实服务端，直接合成一个响应，保证内容与时机完全可控
      // （失败的读取不会读到真实数据，失败的保存也不会在服务端落地）。
      async fulfill(id, status, payload, extraHeaders) {
        const rec = held.get(id);
        if (!rec || rec.done) return;
        rec.done = true;
        const raw = typeof payload === "string" ? payload : JSON.stringify(payload);
        const headers = [
          { name: "Content-Type", value: "application/json; charset=utf-8" },
          { name: "Content-Length", value: String(Buffer.byteLength(raw)) },
        ];
        for (const [name, value] of Object.entries(extraHeaders || {})) {
          headers.push({ name, value: String(value) });
        }
        await cdp.send("Fetch.fulfillRequest", {
          requestId: rec.requestId,
          responseCode: status,
          responseHeaders: headers,
          body: Buffer.from(raw, "utf8").toString("base64"),
        });
      },
      // fail 直接以网络错误终止该请求，模拟连接失败（fetch promise reject）。
      async fail(id, reason) {
        const rec = held.get(id);
        if (!rec || rec.done) return;
        rec.done = true;
        try {
          await cdp.send("Fetch.failRequest", {
            requestId: rec.requestId,
            errorReason: reason || "Failed",
          });
        } catch { /* 请求可能已失效 */ }
      },
      // continueAll 放行所有仍挂着的请求：场景中断时自愈，避免遗留 fetch
      // 永久挂起影响后续场景。
      async continueAll() {
        for (const rec of held.values()) {
          if (!rec.done) {
            rec.done = true;
            try {
              await cdp.send("Fetch.continueRequest", { requestId: rec.requestId });
            } catch { /* ignore */ }
          }
        }
      },
    };

    return {
      // 由共享监听器调用：返回 true 表示该请求归本闸门挂起。
      wants(params) {
        return paused && params.request && params.request.method === method &&
          params.request.url.includes("/api/venues");
      },
      async hold(params) {
        try {
          await onPaused(params);
        } catch { /* 竞态失败交给场景断言处理 */ }
      },
      api,
    };
  }

  const postGate = makeGate("POST");
  const getGate = makeGate("GET");

  cdp.on((eventMethod, params) => {
    if (eventMethod !== "Fetch.requestPaused") return;
    (async () => {
      if (postGate.wants(params)) { await postGate.hold(params); return; }
      if (getGate.wants(params)) { await getGate.hold(params); return; }
      // 未被任何闸门暂停的场地请求（HTML/health 本来就不匹配 urlPattern）
      // 以及闸门 resume 之后到达的请求，一律立即放行。
      try {
        await cdp.send("Fetch.continueRequest", { requestId: params.requestId });
      } catch { /* 请求可能已失效，忽略 */ }
    })().catch(() => { /* 监听器内异常不能冒泡成 unhandledRejection */ });
  });

  return {
    async enable() {
      await cdp.send("Fetch.enable", {
        patterns: [{ urlPattern: "*api/venues*", requestStage: "Request" }],
      });
    },
    post: postGate.api,
    get: getGate.api,
    async continueAll() {
      await postGate.api.continueAll();
      await getGate.api.continueAll();
    },
    // resetAll 恢复暂停状态并放行遗留请求，用于场景异常后的自愈。
    resetAll() {
      postGate.api.resume();
      getGate.api.resume();
      return this.continueAll();
    },
  };
}

